const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const settings = settingsOf('Load settings');
const docs = (settings.brand_doc_urls || '')
  .split(/\s+/)
  .map((u) => u.trim())
  .filter(Boolean)
  .map((url) => {
    const m = url.match(/\/(wiki|docx|docs)\/([A-Za-z0-9]+)/);
    return m ? { url, kind: m[1] === 'wiki' ? 'wiki' : 'docx', token: m[2] } : { url, kind: 'unknown', token: '' };
  });
return [{ json: { settings, docs, has_docs: docs.some((d) => d.kind !== 'unknown') } }];

const token = $json.tenant_access_token;
if (!token) throw new Error('No Lark tenant token: ' + JSON.stringify($json).slice(0, 300));
return $('Read settings').first().json.docs
  .filter((d) => d.kind !== 'unknown')
  .map((d) => ({
    json: {
      ...d,
      auth: token,
      resolve_url: d.kind === 'wiki'
        ? `https://open.larksuite.com/open-apis/wiki/v2/spaces/get_node?token=${d.token}`
        : `https://open.larksuite.com/open-apis/docx/v1/documents/${d.token}`,
    },
  }));

// A wiki link points at a node; the document behind it is node.obj_token.
const requests = $('Doc requests').all();
return $input.all().map((item, i) => {
  const req = requests[i].json;
  const r = item.json || {};
  const data = r.data || {};
  let docId = '';
  let title = '';
  let error = '';
  if (r.code !== 0) {
    error = (r.error && (r.error.message || JSON.stringify(r.error))) || r.msg || 'cannot open';
  } else if (req.kind === 'wiki') {
    const node = data.node || {};
    title = node.title || '';
    if (node.obj_type === 'docx') docId = node.obj_token;
    else error = `wiki page is a ${node.obj_type}, only docs are read`;
  } else {
    docId = (data.document || {}).document_id || req.token;
    title = (data.document || {}).title || '';
  }
  return {
    json: {
      url: req.url,
      title,
      error,
      auth: req.auth,
      raw_url: docId ? `https://open.larksuite.com/open-apis/docx/v1/documents/${docId}/raw_content` : 'https://open.larksuite.com/open-apis/docx/v1/documents/missing/raw_content',
    },
  };
});

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const { settings, docs } = $('Read settings').first().json;
const warnings = docs.filter((d) => d.kind === 'unknown').map((d) => `Not a Lark doc or wiki link: ${d.url}`);
const parts = [];
if (settings.brand_brief) parts.push(`## Brand brief\n${settings.brand_brief}`);

if ($('Read doc').isExecuted) {
  const ids = $('Doc ids').all();
  $('Read doc').all().forEach((item, i) => {
    const meta = ids[i].json;
    const r = item.json || {};
    if (meta.error) warnings.push(`${meta.url}: ${meta.error}`);
    else if (r.code !== 0) warnings.push(`${meta.url}: ${(r.error && r.error.message) || r.msg || 'cannot read'}`);
    else parts.push(`## ${meta.title || meta.url}\n${(r.data && r.data.content) || ''}`);
  });
}

const brand = parts.join('\n\n').slice(0, 40000);
if (!brand.trim()) {
  throw new Error('No brand text: add Lark doc links to brand_doc_urls (and add the Lark app to each doc) or fill brand_brief in content_strategy.settings. ' + warnings.join(' | '));
}

const rules = rowsOf('Load retros')
  .map((r) => `From the ${r.month} retro:\n${(r.rules || '').trim()}`)
  .join('\n\n');
const references = rowsOf('Load references').map((r) => ({
  hook: r.hook,
  why: (r.why_it_works || '').toString().slice(0, 300),
}));

return [{
  json: {
    settings,
    brand,
    rules,
    references,
    warnings,
    page_name: settings.page_name || 'the brand',
    language: settings.content_language || 'Vietnamese',
    post_time: /^\d{1,2}:\d{2}$/.test(settings.post_time || '') ? settings.post_time.padStart(5, '0') : '20:00',
  },
}];
